    'admin.guide.nova_post.what' => 'Branch and courier delivery, waybills and tracking.',
    'admin.guide.nova_post.how' => 'Create an API key in your Nova Post business account (Settings, Security, API keys). Sender references come from the same account; leave the other values at their defaults.',
    'admin.guide.ukrposhta.what' => 'Address classifier and delivery to Ukrposhta offices.',
    'admin.guide.ukrposhta.how' => 'Request API access on the Ukrposhta website after signing a contract; paste the bearer token.',
    'admin.guide.meest.what' => 'Delivery by Meest (contract based).',
    'admin.guide.meest.how' => 'The values come from your Meest integration agreement. Without a contract leave the variables empty.',
    'admin.guide.liqpay.what' => 'Online card payments on a hosted page.',
    'admin.guide.liqpay.how' => 'Open the company in LiqPay business cabinet, copy the public and private keys. Test with LIQPAY_SANDBOX=1 first, then switch it to 0.',
    'admin.guide.monobank.what' => 'Card payments through monobank hosted page.',
    'admin.guide.monobank.how' => 'Get the merchant token in the monobank acquiring cabinet (Settings). Keep the default API address.',
    'admin.guide.wayforpay.what' => 'Online card payments.',
    'admin.guide.wayforpay.how' => 'Create a merchant in the WayForPay cabinet; copy the merchant account, secret key and use the site domain exactly as registered there.',
    'admin.guide.merchant.what' => 'Product feed and free listings in Google.',
    'admin.guide.merchant.how' => 'Account ID is shown in the top bar of Merchant Center. Create a service account in Google Cloud, add it as a user of the Merchant account and paste the JSON path.',
    'admin.guide.ga4.what' => 'Purchases sent from the server with consent.',
    'admin.guide.ga4.how' => 'In GA4 open Admin, Data streams, your web stream: copy the measurement ID and create a Measurement Protocol API secret.',
    'admin.guide.meta.what' => 'Server purchase events for Facebook and Instagram ads.',
    'admin.guide.meta.how' => 'In Events Manager choose the pixel, open Settings, Conversions API and generate an access token.',
    'admin.guide.tiktok.what' => 'Server purchase events for TikTok ads.',
    'admin.guide.tiktok.how' => 'In TikTok Ads Manager open Events, your pixel, Events API and create an access token.',
    'admin.guide.mail.what' => 'Order confirmations, password resets and campaigns.',
    'admin.guide.mail.how' => 'Use the SMTP data of your mail service. Send from an address on your own domain and set SPF and DKIM records there, otherwise letters land in spam. Port 587 with TLS is the usual choice.',
    'admin.guide.telegram.what' => 'New-order messages to a chat.',
    'admin.guide.telegram.how' => 'Create a bot with @BotFather and copy its token. Add the bot to your chat and use the chat ID (a number, negative for groups).',
    'admin.guide.google_login.what' => 'Customers sign in with a Google account.',
    'admin.guide.google_login.how' => 'In Google Cloud create an OAuth client (web application) and add the shop return address from the login page as an authorised redirect URI.',
    'admin.guide.meili.what' => 'Faster search for large catalogues. The built-in search works without it.',
    'admin.guide.meili.how' => 'Needed only for catalogues of tens of thousands of products. Run Meilisearch on the server and paste its address and key.',
